from flask import Flask


def create_app(env):
    """App factory: read the configuration from env (a dict such as os.environ)."""
    app = Flask(__name__)
    app.config["SECRET_KEY"] = env.get("SECRET_KEY", "dev-key")
    app.config["SQLALCHEMY_DATABASE_URI"] = env.get("DATABASE_URL", "sqlite:///app.db")
    app.config["DEBUG"] = env.get("DEBUG", "False").lower() == "true"

    @app.route("/")
    def home():
        return {"status": "running", "debug": app.config["DEBUG"]}

    return app


def procfile_line():
    return "web: gunicorn wsgi:application --bind 0.0.0.0:$PORT"


def gunicorn_command(workers=4, port=8000):
    return f"gunicorn wsgi:application --bind 0.0.0.0:{port} --workers {workers}"


def requirements_txt(packages):
    return "\n".join(f"{name}=={version}" for name, version in sorted(packages.items()))


# wsgi.py would contain:  application = create_app(os.environ)
application = create_app({"SECRET_KEY": "prod-secret", "DATABASE_URL": "postgresql://db.example/app"})
client = application.test_client()
print(client.get("/").get_json())
print(procfile_line())
print(gunicorn_command())
print(requirements_txt({"gunicorn": "22.0.0", "flask": "3.0.3"}))
